"use client";

import { useState, useEffect } from "react";
import axios from "axios";
import { useRouter } from "next/navigation";
import { Search, X } from "lucide-react";

import api from "@/services/api";

const ListPage = ({ keys, modelName, onEdit, setListUpdateHandler }) => {
  const router = useRouter();

  const token =
    typeof window !== "undefined"
      ? localStorage.getItem("token")
      : null;

  const [listData, setListData] = useState([]);
  const [message, setMessage] = useState("");
  const [searchTerm, setSearchTerm] = useState("");

  const [page, setPage] = useState(0);
  const [sizePerPage] = useState(4);
  const [totalPages, setTotalPages] = useState(0);

  const normalizedSearch = searchTerm.trim().toLowerCase();
  const isSearching = normalizedSearch.length > 0;

  const paginationDto = {
    page: isSearching ? 0 : page,
    sizePerPage: isSearching ? 1000 : sizePerPage,
  };

  const getItemIdentifier = (item, rowIndex) =>
    item?.identifier ?? item?.id ?? item?.username ?? `${modelName}-${rowIndex}`;

  const filteredData = listData
    .map((item, rowIndex) => ({ item, rowIndex }))
    .filter(({ item }) => {
      if (!normalizedSearch) return true;

      return keys.some((key) =>
        String(item?.[key] ?? "")
          .toLowerCase()
          .includes(normalizedSearch)
      );
    });

  const fetchList = async () => {
    try {
      const res = await api.post(
        `/${modelName}/list`,
        paginationDto,
        {
          headers: {
            Authorization: `Bearer ${token}`,
            "Content-Type": "application/json",
          },
        }
      );

      setListData(res.data.dtoList || []);
      setTotalPages(res.data.totalPages || 0);

    } catch (err) {
      console.error(err);
      setMessage("Failed to load data");
    }
  };

  const handleToggleStatus = (rowIndex) => {
    const updatedList = [...listData];

    updatedList[rowIndex].status = !updatedList[rowIndex].status;
    setListData(updatedList);

    api.post(
      `/${modelName}/toggle`,
      {
        identifier: updatedList[rowIndex].identifier,
        status: updatedList[rowIndex].status,
      },
      {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      }
    );
  };

  const handleDelete = async (identifier) => {
    if (window.confirm("Are you sure you want to delete this item?")) {
      try {
        await axios.get(
          `http://localhost:8080/api/${modelName}/delete?identifier=${identifier}`,
          {
            headers: {
              Authorization: `Bearer ${token}`,
            },
          }
        );

        setMessage(`${modelName} deleted successfully`);
        setTimeout(() => setMessage(""), 3000);

        fetchList();

      } catch (err) {
        console.error(err);
        setMessage("Delete failed");
      }
    }
  };

  const handleUpdateSuccess = (updatedItem) => {
    setListData((prev) =>
      prev.map((item, rowIndex) =>
        getItemIdentifier(item, rowIndex) === getItemIdentifier(updatedItem, rowIndex)
          ? updatedItem
          : item
      )
    );
  };

  useEffect(() => {
    fetchList();
  }, [modelName, page, isSearching]);

  useEffect(() => {
    setPage(0);
  }, [searchTerm]);

  useEffect(() => {
    setListUpdateHandler?.(() => handleUpdateSuccess);
  }, []);

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-100 to-blue-300 p-6">
      <div className="max-w-6xl mx-auto">

        {/* Title */}
        <h2 className="text-3xl font-bold text-white text-center mb-6">
          {modelName.charAt(0).toUpperCase() + modelName.slice(1)} List
        </h2>

        {/* Toast */}
        {message && (
          <div className="fixed bottom-6 left-1/2 -translate-x-1/2 bg-white/30 backdrop-blur-lg px-6 py-3 rounded-xl shadow-lg text-sm">
            {message}
          </div>
        )}

        {/* Table */}
        <div className="bg-white/90 rounded-2xl shadow-xl p-6">
          <div className="mb-5 flex justify-end">
            <div className="relative w-full max-w-sm">
              <Search
                size={18}
                className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400"
              />

              <input
                type="text"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                placeholder={`Search ${modelName}`}
                className="w-full rounded-xl border border-gray-300 bg-white py-2.5 pl-10 pr-10 text-sm text-gray-800 outline-none transition focus:border-blue-500 focus:ring-2 focus:ring-blue-200"
              />

              {searchTerm && (
                <button
                  type="button"
                  onClick={() => setSearchTerm("")}
                  className="absolute right-2 top-1/2 -translate-y-1/2 rounded-lg p-1 text-gray-400 transition hover:bg-gray-100 hover:text-gray-700"
                  aria-label="Clear search"
                >
                  <X size={16} />
                </button>
              )}
            </div>
          </div>

          {filteredData.length === 0 ? (
            <div className="text-center text-gray-600">
              {searchTerm ? "No matching data found" : "No data found"}
            </div>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full border-collapse">

                <thead>
                  <tr className="border-b">
                    {keys.map((key) => (
                      <th key={key} className="py-3 px-3 text-left">
                        {key}
                      </th>
                    ))}
                    <th>Actions</th>
                  </tr>
                </thead>

                <tbody>
                  {filteredData.map(({ item, rowIndex }) => (
                    <tr key={getItemIdentifier(item, rowIndex)} 
                    className="border-b hover:bg-blue-100/40 transition">

                      {keys.map((key, colIndex) =>
                        key === "status" ? (
                          <td key={colIndex} className="py-3 px-3">
                            <label className="relative inline-flex items-center cursor-pointer">
  
                            <input
                              type="checkbox"
                              className="sr-only peer"
                              checked={item[key] === true}
                              onChange={() => handleToggleStatus(rowIndex)}
                            />

                            {/* Track */}
                            <div
                              className="
                                w-11 h-6 bg-gray-300 rounded-full
                                peer-checked:bg-green-500
                                transition-colors duration-300
                              "
                            />

                            {/* Thumb */}
                            <div
                              className="
                                absolute
                                left-1 top-1
                                w-4 h-4 bg-white rounded-full shadow
                                transform transition-transform duration-300
                                peer-checked:translate-x-5
                              "
                            />

                          </label>
                          </td>
                        ) : (
                          <td key={colIndex}>
                            {key === "id"
                              ? (isSearching ? rowIndex : page * sizePerPage + rowIndex) + 1
                              : String(item[key])}
                          </td>
                        )
                      )}

                      <td className="py-3 px-3">
                        <div className="flex gap-2">
                          <button
                            onClick={() => onEdit(getItemIdentifier(item, rowIndex), fetchList)}
                            className="bg-blue-600 hover:bg-blue-700 text-white px-3 py-1 rounded-lg shadow"
                          >
                            Update
                          </button>

                          <button
                            onClick={() => handleDelete(getItemIdentifier(item, rowIndex))}
                            className="bg-red-600 hover:bg-red-700 text-white px-3 py-1 rounded-lg shadow"
                          >
                            Delete
                          </button>
                        </div>
                      </td>

                    </tr>
                  ))}
                </tbody>

              </table>

              {/* Pagination */}
              {!isSearching && (
                <div className="flex justify-center gap-3 mt-4">
                  <button
                    disabled={page === 0}
                    onClick={() => setPage((p) => p - 1)}
                    className="px-3 py-1 bg-gray-300 rounded"
                  >
                    Prev
                  </button>

                  <span className="px-2">
                    Page {page + 1} of {totalPages}
                  </span>

                  <button
                    disabled={page >= totalPages - 1}
                    onClick={() => setPage((p) => p + 1)}
                    className="px-3 py-1 bg-gray-300 rounded"
                  >
                    Next
                  </button>
                </div>
              )}

            </div>
          )}
        </div>

        {/* Navigation */}
        <div className="flex justify-center gap-4 mt-6">
          <button
            onClick={() => router.push("/home")}
            className="bg-gray-500 hover:bg-gray-600 text-white px-4 py-2 rounded-lg"
          >
            Home
          </button>

          <button
            onClick={() => router.push(`/${modelName}/Add`)}
            className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg shadow"
          >
            + Add {modelName}
          </button>
        </div>

      </div>
    </div>
  );
};

export default ListPage;

