"use client";

import { useState, useEffect } from "react";
import PropTypes from "prop-types";
import api from "@/services/api";

const Roles = ({ formData = {}, handleChange, options = [], disableFetch = false, errors = {} }) => {
  const [roles, setRoles] = useState(options);

  const getRoleValue = (role) => role?.identifier || role?.name || role;

  let selectedRoles = [];

  if (Array.isArray(formData.roles)) {
    selectedRoles = formData.roles.map(getRoleValue);
  } else if (formData.roles) {
    selectedRoles = [getRoleValue(formData.roles)];
  }

  const updateSelectedRoles = (selected) => {
    handleChange?.({
      target: {
        name: "roles",
        value: selected,
      },
    });
  };

  const toggleRole = (roleValue) => {
    const selected = selectedRoles.includes(roleValue)
      ? selectedRoles.filter((role) => role !== roleValue)
      : [...selectedRoles, roleValue];

    updateSelectedRoles(selected);
  };

  const fetchRoles = async () => {
    let token = null;

  if (globalThis.localStorage !== undefined) {
    token = globalThis.localStorage.getItem("token");
  }

    const paginationDto = {
      page: 0,
      sizePerPage: 50,
    };

    try {
      const response = await api.post(
        "/role/list",
        paginationDto,
        {
          headers: {
            Authorization: `Bearer ${token}`,
            "Content-Type": "application/json",
          },
        }
      );

      setRoles(
        Array.isArray(response.data)
          ? response.data
          : response.data?.dtoList || response.data?.content || []
      );
    } catch (error) {
      console.error(error);
    }
  };

  useEffect(() => {
    if (options.length > 0) {
      setRoles(options);
      return;
    }

    if (disableFetch) return;

    fetchRoles();
  }, [options, disableFetch]);

  return (
  <div className="w-full">
    <label htmlFor="roles" className="block mb-2 text-sm font-semibold text-gray-700">
      Role
    </label>

    <select
      name="roles"
      multiple
      value={selectedRoles}
      onChange={(e) => {
        const selected = Array.from(e.target.selectedOptions).map(
          (opt) => opt.value
        );

        updateSelectedRoles(selected);
      }}
      className="
        w-full
        rounded-xl
        border
        border-gray-300
        bg-white
        px-4
        py-3
        focus:outline-none
        focus:ring-2
        focus:ring-blue-500
      "
    >
      {roles.map((role, index) => (
        <option
          key={getRoleValue(role) || index}
          value={getRoleValue(role)}
          onMouseDown={(e) => {
            e.preventDefault();
            toggleRole(getRoleValue(role));
          }}
        >
          {getRoleValue(role)}
        </option>
      ))}
    </select>

    {errors.roles && (
      <p className="mt-2 text-sm text-red-500">
        {errors.roles}
      </p>
    )}
  </div>
);
};

Roles.propTypes = {
  formData: PropTypes.object,
  handleChange: PropTypes.func,
  options: PropTypes.array,
  disableFetch: PropTypes.bool,
  errors: PropTypes.object,
};

export default Roles;

import { useState, useEffect } from "react";

import api from "@/services/api";

const SubCategories = ({ formData = {}, handleChange, errors = {} }) => {
    const [categories, setCategories] = useState([]);

    const fetchCategories = async () => {
        const token = localStorage.getItem("token");

        const headers = {
            Authorization: `Bearer ${token}`,
            "Content-Type": "application/json",
        };

        try {
            const response = await api.get(
                `/category/listSuperCategory`,
                { headers }
            );

            setCategories(response.data || []);
        } catch (error) {
            console.error(error);
        }
    };

    useEffect(() => {
        fetchCategories();
    }, []);

    return (
        <div className="w-full">
            <label className="block mb-2 text-sm font-semibold text-gray-700">
                Category
            </label>

            <select
                name="category"
                multiple
                value={Array.isArray(formData.category) ? formData.category : []}
                onChange={(e) => {
                    const selected = Array.from(e.target.selectedOptions).map(
                        (opt) => opt.value
                    );

                    handleChange({
                        target: {
                            name: "category",
                            value: selected,
                        },
                    });
                }}
                className="
                    w-full
                    rounded-xl
                    border
                    border-gray-300
                    bg-white
                    px-4
                    py-3
                    focus:outline-none
                    focus:ring-2
                    focus:ring-blue-500
                "
            >

                {categories.map((category) => (
                    <option
                        key={category.identifier}
                        value={category.name}
                    >
                        {category.name}
                    </option>
                ))}
            </select>
            {errors.category && (
                <p className="mt-2 text-sm text-red-500">
                    {errors.category}
                </p>
            )}
        </div>
    );
};

export default SubCategories;

"use client";

import { useState, useEffect } from "react";

import api from "@/services/api";

const Units = ({ formData = {}, handleChange, errors = {} }) => {
  const [units, setUnits] = useState([]);

  const fetchUnits = async () => {
    const token =
      typeof window !== "undefined"
        ? localStorage.getItem("token")
        : null;

    const paginationDto = {
      page: 0,
      sizePerPage: 50,
    };

    try {
      const response = await api.post(
        "/unit/list",
        paginationDto,
        {
          headers: {
            Authorization: `Bearer ${token}`,
            "Content-Type": "application/json",
          },
        }
      );

      setUnits(
        Array.isArray(response.data)
          ? response.data
          : response.data?.dtoList || []
      );
    } catch (error) {
      console.error(error);
    }
  };

  useEffect(() => {
    fetchUnits();
  }, []);

  return (
    <div className="w-full">
      <label className="block mb-2 text-sm font-semibold text-gray-700">
        Unit
      </label>

      <select
        name="unit"
        value={formData.unit || ""}
        onChange={handleChange}
        className="
          w-full
          rounded-xl
          border
          border-gray-300
          bg-white
          px-4
          py-3
          focus:outline-none
          focus:ring-2
          focus:ring-blue-500
        "
      >
        <option value="">Select Unit</option>

        {units.map((unit) => (
          <option
            key={unit.identifier}
            value={unit.identifier}
          >
            {unit.identifier}
          </option>
        ))}
      </select>
    </div>
  );
};

export default Units;
